<script setup>import{router,usePage}from'@inertiajs/vue3';import{ref}from'vue';import AppLayout from'../../Layouts/AppLayout.vue';import ProductCard from'../../Components/ProductCard.vue';import ProductDescription from'../../Components/ProductDescription.vue';import SeoHead from'../../Components/SeoHead.vue';const props=defineProps({product:Object,related:Array}),qty=ref(1),page=usePage(),money=v=>new Intl.NumberFormat('en-TZ',{style:'currency',currency:page.props.store.currency,maximumFractionDigits:0}).format(v||0);const add=()=>router.post(`/cart/${props.product.slug}`,{quantity:qty.value});const schema={'@context':'https://schema.org','@type':'Product',name:props.product.name,image:[props.product.image_url,...(props.product.gallery_urls||[])],description:props.product.meta_description||props.product.short_description,sku:props.product.sku,brand:props.product.brand?{'@type':'Brand',name:props.product.brand.name}:undefined,offers:{'@type':'Offer',priceCurrency:page.props.store.currency,price:props.product.current_price,availability:props.product.in_stock?'https://schema.org/InStock':'https://schema.org/OutOfStock'}};</script><template><AppLayout><SeoHead :title="product.meta_title||product.name" :description="product.meta_description||product.short_description" :image="product.image_url" :schema="schema"/><div class="container-shell py-8"><div class="grid gap-8 lg:grid-cols-2"><div><img :src="product.image_url" :alt="product.name" class="card aspect-square w-full object-cover"><div v-if="product.gallery_urls?.length" class="mt-3 grid grid-cols-4 gap-2"><img v-for="img in product.gallery_urls" :key="img" :src="img" class="aspect-square rounded-[8px] border object-cover"></div></div><div><p class="text-xs font-black uppercase tracking-wider text-prinx-600">{{product.brand?.name}} · {{product.category?.name}}</p><h1 class="mt-2 text-3xl font-black">{{product.name}}</h1><p class="mt-3 text-slate-500">{{product.short_description}}</p><div class="mt-5 text-3xl font-black">{{money(product.current_price)}}</div><p v-if="Number(product.current_price)<Number(product.price)" class="text-sm text-slate-400 line-through">{{money(product.price)}}</p><div class="mt-5 flex items-center gap-3"><input v-model.number="qty" type="number" min="1" max="99" class="input w-24"><button class="btn-primary flex-1" :disabled="!product.in_stock" @click="add">{{product.in_stock?'Add to cart':'Out of stock'}}</button></div><div class="mt-6 grid grid-cols-2 gap-3 text-sm"><div class="card p-3"><b>SKU</b><p class="text-slate-500">{{product.sku}}</p></div><div class="card p-3"><b>Warranty</b><p class="text-slate-500">{{product.warranty||'Contact us'}}</p></div></div><div v-if="product.specifications" class="mt-6"><h2 class="font-black">Specifications</h2><dl class="mt-3 divide-y rounded-[10px] border bg-white"><div v-for="(v,k) in product.specifications" :key="k" class="grid grid-cols-2 gap-3 p-3 text-sm"><dt class="font-bold">{{k}}</dt><dd class="text-slate-500">{{v}}</dd></div></dl></div></div></div><section class="mt-10"><h2 class="text-xl font-black">Product details</h2><div class="card mt-3 p-5"><ProductDescription :content="product.description"/></div></section><section v-if="related?.length" class="mt-10"><h2 class="text-xl font-black">You may also like</h2><div class="mt-4 grid grid-cols-2 gap-3 md:grid-cols-4"><ProductCard v-for="p in related" :key="p.id" :product="p" compact-mobile/></div></section></div></AppLayout></template>
